from math import lcm
from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Return the k-th positive integer that is a multiple of a coin denomination.

    Each denomination contributes all of its positive multiples, and amounts are
    counted only once even when they are multiples of more than one denomination.
    """
    if k < 1:
        raise ValueError("k must be at least 1")
    if not coins:
        raise ValueError("at least one coin denomination is required")

    # A denomination which is a multiple of a smaller denomination adds no
    # amounts to the union, so it can be discarded.
    denominations = []
    for coin in sorted(set(coins)):
        if coin <= 0:
            raise ValueError("coin denominations must be positive")
        if not any(coin % smaller == 0 for smaller in denominations):
            denominations.append(coin)

    # The k-th multiple of the smallest denomination is a guaranteed upper bound.
    upper = denominations[0] * k

    # Inclusion-exclusion terms for the union of the sets of multiples. Combine
    # subsets with the same LCM to keep counting compact, and ignore LCMs larger
    # than the search bound (they contribute zero throughout the search).
    terms = {}
    for coin in denominations:
        additions = {coin: 1}
        for common_multiple, coefficient in terms.items():
            combined_lcm = lcm(common_multiple, coin)
            if combined_lcm <= upper:
                additions[combined_lcm] = additions.get(combined_lcm, 0) - coefficient
        for common_multiple, coefficient in additions.items():
            terms[common_multiple] = terms.get(common_multiple, 0) + coefficient
            if terms[common_multiple] == 0:
                del terms[common_multiple]

    def count_at_most(amount: int) -> int:
        return sum(coefficient * (amount // common_multiple)
                   for common_multiple, coefficient in terms.items())

    low, high = 1, upper
    while low < high:
        middle = (low + high) // 2
        if count_at_most(middle) >= k:
            high = middle
        else:
            low = middle + 1
    return low
